ALTER TABLE public.topic_markers ADD COLUMN active boolean NOT NULL DEFAULT true;
ALTER TABLE public.quiz_questions ADD COLUMN active boolean NOT NULL DEFAULT true;
CREATE OR REPLACE FUNCTION public.replace_lesson_content(_lesson uuid,_title text,_youtube text,_source text,_chunks jsonb,_generated jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE lid uuid; m jsonb; q jsonb; mid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _lesson IS NULL THEN INSERT INTO lessons(title,youtube_id,source,owner_id,transcript_status,duration_sec,summary,note) VALUES(_title,_youtube,_source,auth.uid(),'provided',(SELECT max((c->>'end_sec')::int) FROM jsonb_array_elements(_chunks)c),_generated->>'summary',_generated->>'summary') RETURNING id INTO lid; ELSE IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only an admin can replace a lesson transcript'; END IF; SELECT id INTO lid FROM lessons WHERE id=_lesson; IF lid IS NULL THEN RAISE EXCEPTION 'Lesson not found'; END IF; UPDATE lessons SET transcript_status='provided',summary=_generated->>'summary',note=_generated->>'summary',duration_sec=(SELECT max((c->>'end_sec')::int) FROM jsonb_array_elements(_chunks)c) WHERE id=lid; UPDATE quiz_questions SET active=false WHERE lesson_id=lid; UPDATE topic_markers SET active=false WHERE lesson_id=lid; DELETE FROM transcript_chunks WHERE lesson_id=lid; END IF; INSERT INTO transcript_chunks(lesson_id,start_sec,end_sec,text) SELECT lid,(c->>'start_sec')::int,(c->>'end_sec')::int,c->>'text' FROM jsonb_array_elements(_chunks)c; FOR m IN SELECT * FROM jsonb_array_elements(_generated->'markers') LOOP INSERT INTO topic_markers(lesson_id,start_sec,title,summary) VALUES(lid,(m->>'start_sec')::int,m->>'title',m->>'summary'); END LOOP; FOR q IN SELECT * FROM jsonb_array_elements(_generated->'questions') LOOP SELECT id INTO mid FROM topic_markers WHERE lesson_id=lid AND active AND start_sec<=(q->>'source_start_sec')::int ORDER BY start_sec DESC LIMIT 1; INSERT INTO quiz_questions(lesson_id,topic_marker_id,question,options,answer_index,explanation,source_start_sec) VALUES(lid,mid,q->>'question',q->'options',(q->>'answer_index')::int,q->>'explanation',(q->>'source_start_sec')::int); END LOOP; RETURN lid; END $$;
GRANT SELECT(active) ON public.quiz_questions TO anon,authenticated;
REVOKE INSERT ON public.ai_requests FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.has_role FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role TO authenticated,service_role;
REVOKE EXECUTE ON FUNCTION public.quiz_attempt_to_revision FROM PUBLIC,anon,authenticated;
REVOKE INSERT,UPDATE ON public.interview_sessions FROM authenticated;
REVOKE INSERT ON public.interview_turns,public.explanation_attempts FROM authenticated;